/// Product status based on expiration date
enum ProductStatus {
  fresh,
  expiringSoon,
  expired;

  /// Get status color for the given color scheme
  Color getColor(ColorScheme colorScheme) {
    switch (this) {
      case ProductStatus.fresh:
        return colorScheme.primary;
      case ProductStatus.expiringSoon:
        return colorScheme.tertiary;
      case ProductStatus.expired:
        return colorScheme.error;
    }
  }

  /// Get status message
  String getMessage() {
    switch (this) {
      case ProductStatus.fresh:
        return 'product.status_fresh'.tr();
      case ProductStatus.expiringSoon:
        return 'product.status_expires_soon'.tr();
      case ProductStatus.expired:
        return 'product.status_expired'.tr();
    }
  }

  /// Get status icon
  IconData getIcon() {
    switch (this) {
      case ProductStatus.fresh:
        return Icons.check_circle_outline;
      case ProductStatus.expiringSoon:
        return Icons.warning_amber_rounded;
      case ProductStatus.expired:
        return Icons.error_outline;
    }
  }
}

/// Entry for a specific quantity expiring on a specific date
@freezed
abstract class ExpiryEntry with _$ExpiryEntry {
  const ExpiryEntry._();
  const factory ExpiryEntry({
    required int quantity,
    required DateTime expirationDate,
  }) = _ExpiryEntry;

  factory ExpiryEntry.fromJson(Map<String, Object?> json) =>
      _$ExpiryEntryFromJson(json);

  Map<String, dynamic> toFirestoreRest() {
    return {
      'mapValue': {
        'fields': {
          'quantity': {'integerValue': quantity.toString()},
          'expirationDate': {'stringValue': expirationDate.toIso8601String()},
        },
      },
    };
  }

  bool get isExpired {
    final now = DateTime.now();
    final today = DateTime(now.year, now.month, now.day);
    final expiry = DateTime(
      expirationDate.year,
      expirationDate.month,
      expirationDate.day,
    );
    return expiry.isBefore(today);
  }

  bool get isExpiringToday {
    final now = DateTime.now();
    final today = DateTime(now.year, now.month, now.day);
    final expiry = DateTime(
      expirationDate.year,
      expirationDate.month,
      expirationDate.day,
    );
    return expiry.isAtSameMomentAs(today);
  }

  int get daysUntilExpiration {
    final now = DateTime.now();
    final today = DateTime(now.year, now.month, now.day);
    final expiry = DateTime(
      expirationDate.year,
      expirationDate.month,
      expirationDate.day,
    );
    return expiry.difference(today).inDays;
  }
}

@freezed
abstract class Product with _$Product {
  const Product._();
  const factory Product({
    required String id,
    required String name,
    required String description,
    required String userId, // Owner of the product
    @Default([])
    List<ExpiryEntry> expiries, // Quantities and their expiration dates
    @Default(0) int nonExpiringQuantity,
    String? category,
    String? imageUrl,
    String? barcode,
    @Default(false) bool isGlobal,

    /// registryType -> Scope in the shared `products` collection.
    /// - global: globally shared registry products
    /// - personal: user-owned registry products (templates)
    /// - current: concrete products used in inventories/shopping lists
    @Default('current') String registryType,
    String? mappedFromProductId,
    @Default([])
    List<String> tags, // Labels and tags from APIs like OpenFoodFacts
  }) = _Product;

  factory Product.fromJson(Map<String, Object?> json) =>
      _$ProductFromJson(json);

  // Helper method to get total quantity
  int get quantity =>
      nonExpiringQuantity +
      expiries.fold(0, (sum, entry) => sum + entry.quantity);

  // Helper method to get the soonest expiration date
  DateTime? get soonestExpirationDate {
    if (expiries.isEmpty) return null;
    return expiries
        .map((e) => e.expirationDate)
        .reduce((a, b) => a.isBefore(b) ? a : b);
  }

  // Helper method to check if any quantity is expired
  bool get isExpired {
    return expiries.any((e) => e.isExpired);
  }

  // Helper method to check if any quantity is expiring today
  bool get isExpiringToday {
    return expiries.any((e) => e.isExpiringToday);
  }

  // Helper method to check if any quantity is expiring soon (within 1–6 days)
  bool get isExpiringSoon {
    return expiries.any((e) {
      final days = e.daysUntilExpiration;
      return days > 0 && days <= 6;
    });
  }

  // Soonest days until expiration (negative if expired)
  int? get daysUntilExpiration {
    if (expiries.isEmpty) return null;
    return expiries
        .map((e) => e.daysUntilExpiration)
        .reduce((a, b) => a < b ? a : b);
  }

  // Get product status based on expiration
  ProductStatus get status {
    if (isExpired) return ProductStatus.expired;
    if (isExpiringToday || isExpiringSoon) return ProductStatus.expiringSoon;
    return ProductStatus.fresh;
  }

  /// Get a friendly status message for display
  String getFriendlyStatus({bool compact = false}) {
    final days = daysUntilExpiration;
    if (isExpired) {
      return compact
          ? 'product.status_compact_exp'.tr()
          : 'product.status_expired'.tr();
    }
    if (isExpiringToday) return 'product.status_today'.tr();
    if (days != null && days > 0) {
      return 'product.status_days_remaining'.tr(
        namedArgs: {'days': days.toString()},
      );
    }
    return status.getMessage();
  }

  Map<String, dynamic> toFirestoreRest() {
    return {
      'id': {'integerValue': id},
      'name': {'stringValue': name},
      'description': {'stringValue': description},
      'userId': {'stringValue': userId},
      'expiries': {
        'arrayValue': {
          'values': expiries.map((e) => e.toFirestoreRest()).toList(),
        },
      },
      'nonExpiringQuantity': {'integerValue': nonExpiringQuantity.toString()},
      'category': {'stringValue': category ?? ''},
      'imageUrl': {'stringValue': imageUrl ?? ''},
      'barcode': {'stringValue': barcode ?? ''},
      'isGlobal': {'booleanValue': isGlobal},
      'tags': {
        'arrayValue': {
          'values': tags.map((t) => {'stringValue': t}).toList(),
        },
      },
    };
  }
}
# Module and context relations

This document describes the relationships between the different domains and contexts within `foodsavr`.
It defines how data flows between components and establishes the core data models used across the application.

## Domain architecture

`foodsavr` uses a domain-driven approach to maintain a structured and clean implementation.
Each context represents a specific area of functionality within the application.

All primary entities in the database inherit from a common `BaseEntity`:

```mermaid
classDiagram
    class BaseEntity {
        + ID
        + CreatedAt
        + UpdatedAt
    }
```

## Core contexts

The following sections define the primary contexts and their respective data models.

### Administration

The administration context governs system-wide data and user management. Use the 
`AdminService` to perform administrative actions and maintain global lists.

- **SuperAdmin:** The primary administrator responsible for managing users, groups, and system settings.
- **Admin:** Handles the moderation of global product, recipe, and meal lists.
- **Democratic curation:** Implement a voting system where you can propose new global items, which are added to the official list based on community feedback.

### User management

The user context handles authentication, profile management, and personal data ownership.

- **Authentication:** Support standard credentials and third-party logins.
- **Data ownership:** Maintain personal copies of shared items (copy-on-add) to ensure your data remains accessible even if a group is disbanded.

```mermaid
classDiagram
    direction LR

    class IUserRepository {
        <<Repository>>
        + Create()
        + Update()
        + Delete()
        + GetByID()
        + Get()
    }

    class IUserService {
        <<Service>>
        + Register()
        + Login()
        + GeneratePasswordResetToken()
        + ChangePassword()
        + LoginWithThirdParty()
    }

    class User {
        <<Aggregate Root>>
        + Email
        + Role -- User, Admin, SuperAdmin
        + LoginAttempts
        + LastLoginDate
    }

    IUserRepository --> User
    IUserService --> User
```

### Groups and collaboration

The group context enables data sharing and coordination among multiple users.

- **Sharing:** Groups share data by filtering queries through group membership IDs.
- **Invitations:** Create groups and invite others via email. Responses are processed through unique invitation links.

```mermaid
classDiagram
    direction LR

    class IGroupRepository {
        <<Repository>>
        + Create()
        + Update()
        + Delete()
        + GetByID()
        + Get()
    }

    class IGroupService {
        <<Service>>
        + InviteUser()
        + RemoveUser()
        + ProcessInviteResponse()
    }

    class Group {
        <<Aggregate Root>>
        + Name
    }

    class GroupMemberships {
        + UserID
        + GroupID
        + Status -- LEADER, MEMBER, INVITED, DECLINED, REMOVED
    }

    IGroupRepository --> Group
    IGroupService --> Group
    Group --> GroupMemberships
```

### Products and inventory

The products and inventory contexts track the food items you own and where they 
are stored.

- **Storage locations:** Categorize items by location (fridge, freezer, or cabinet).
- **Inventory events:** Automatically track missing products to populate shopping lists.

```mermaid
classDiagram
    direction LR

    class IProductRepository {
        <<Repository>>
        + Create()
        + Update()
        + Delete()
        + GetByID()
        + Get()
    }

    class Product {
        <<Aggregate Root>>
        + Name
        + Description
        + Price
        + HomeLocation
        + Category
        + ExpirationDate
        + UserID
        + Global (Boolean)
    }

    class Inventory {
        <<Aggregate Root>>
        + ProductID
        + CurrentQuantity
        + MinimumQuantity
    }

    IProductRepository --> Product
    Inventory --> Product
```

### Recipes and meals

Manage your cooking repertoire through recipes and grouped meal plans.

- **Recipes:** Store ingredients and instructions.
- **Meals:** Group recipes together for scheduling.
- **Meal plans:** Synchronize meals with the Gregorian calendar and link them to the shopping list context.

```mermaid
classDiagram
    direction LR

    class Recipe {
        <<Aggregate Root>>
        + Name
        + RecipeType
        + Price
        + UserID
        + Global (Boolean)
    }

    class Meal {
        <<Aggregate Root>>
        + Name
        + MealType
        + UserID
        + Global (Boolean)
    }

    class MealPlanEntry {
        + MealID
        + Date
        + RecurrenceRule
    }

    Recipe --> Product
    Meal --> Recipe
    MealPlanEntry --> Meal
```

### Shopping lists

The shopping list context manages items to be purchased, informed by your current inventory and upcoming meal plans.

- **Priority:** Flag items as high priority based on critical inventory deficits.
- **Auto-fulfillment:** Mark items as purchased to automatically update your inventory records.

```mermaid
